pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(address _logger, bool _status) internal {
        bool reverted;
        try c.setApprovedLogger(_logger, _status) { reverted = false; } catch { reverted = true; }
        bool recorded;
        try c.approvedToLog(_logger) returns (bool __r) { recorded = __r; } catch { return; }
        assertTrue(reverted || recorded == _status);
    }

    function testFuzz_run(address _logger, bool _status) public {
        vm.assume(_logger.code.length == 0 && uint160(_logger) > 0xffff && _logger != address(this) && _logger != address(c) && _logger != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _logger != 0x000000000000000000636F6e736F6c652e6c6f67 && _logger != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _logger != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_logger, _status);
    }

